import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import { SidebarLayout, type BreadcrumbItem, type NavGroup, type SidebarLayoutProps, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}

import { FirstRunEmpty, PageHeader } from '@gntik-ai/blocks';
import { Page, type BreadcrumbItem, type NavGroup, type UserMenuUser, type Workspace } from '@gntik-ai/ui';
import type { ReactNode } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import { shellSidebarBreadcrumbs, shellSidebarCopy, shellSidebarNav, shellSidebarUser, shellSidebarWorkspaces } from './data';

export interface ShellSidebarPageProps {
  nav: NavGroup[];
  currentHref: string;
  breadcrumbs: BreadcrumbItem[] | null;
  workspaces: Workspace[] | null;
  user: UserMenuUser | null;
  title: ReactNode;
  description: ReactNode;
  emptyTitle: ReactNode;
  emptyDescription: ReactNode;
  emptyActionLabel: string;
  emptySteps: string[];
  /** Primary action of the empty state. */
  onCreate: () => void;
  /** Replaces the empty state with real page content. */
  children: ReactNode;
  /** Other ConsoleShell props (sidebar footer, workspace callbacks, topbar…). */
  shell: Omit<ConsoleShellProps, 'children'>;
}

/** Console starter: ConsoleShell around an empty Page (title, description, first-run state). */
export default function ShellSidebarPage({
  nav = shellSidebarNav,
  currentHref = shellSidebarCopy.currentHref,
  breadcrumbs = shellSidebarBreadcrumbs,
  workspaces = shellSidebarWorkspaces,
  user = shellSidebarUser,
  title = shellSidebarCopy.title,
  description = shellSidebarCopy.description,
  emptyTitle = shellSidebarCopy.emptyTitle,
  emptyDescription = shellSidebarCopy.emptyDescription,
  emptyActionLabel = shellSidebarCopy.emptyActionLabel,
  emptySteps = shellSidebarCopy.emptySteps,
  onCreate,
  children,
  shell,
}: Partial<ShellSidebarPageProps>) {
  return (
    <ConsoleShell nav={nav} currentHref={currentHref} breadcrumbs={breadcrumbs} workspaces={workspaces} user={user} {...shell}>
      <Page header={<PageHeader breadcrumbs={null} title={title} description={description} status="" meta={[]} actions={[]} tabs={null} />}>
        {children ?? (
          <FirstRunEmpty
            titleAs="h2"
            title={emptyTitle}
            description={emptyDescription}
            actionLabel={emptyActionLabel}
            onAction={onCreate}
            steps={emptySteps}
          />
        )}
      </Page>
    </ConsoleShell>
  );
}

import { appSidebarNavGroups, appSidebarUser, appSidebarWorkspaces, firstRunSteps } from '@gntik-ai/blocks';
import type { BreadcrumbItem } from '@gntik-ai/ui';

export { appSidebarNavGroups as shellSidebarNav, appSidebarUser as shellSidebarUser, appSidebarWorkspaces as shellSidebarWorkspaces };

export const shellSidebarBreadcrumbs: BreadcrumbItem[] = [{ label: 'Acme Industries', href: '/overview' }, { label: 'Projects' }];

export const shellSidebarCopy = {
  currentHref: '/projects',
  title: 'Projects',
  description: 'Services, environments and deployments, grouped by project.',
  emptyTitle: 'Create your first project',
  emptyDescription: 'Projects group your services, environments and deployments. Start one from a repository in a couple of minutes.',
  emptyActionLabel: 'New project',
  emptySteps: firstRunSteps,
};
